// ZYVOQIX modification to Beachy Beachy Ball (AGPL-3.0-or-later): touch buttons feed the game's existing keyboard controls.
(()=>{
 const active=new Map();const bar=document.createElement('div');bar.setAttribute('aria-label','Touch controls');bar.style.cssText='position:fixed;bottom:max(10px,env(safe-area-inset-bottom));left:10px;right:10px;display:flex;gap:7px;justify-content:space-between;z-index:100;pointer-events:none';
 const held=new Set();function key(code,down){const values={ArrowLeft:'ArrowLeft',ArrowRight:'ArrowRight',ArrowUp:'ArrowUp',ArrowDown:'ArrowDown',Space:' '};if(down)held.add(code);else held.delete(code);window.dispatchEvent(new KeyboardEvent(down?'keydown':'keyup',{key:values[code],code,bubbles:true}));}
 for(const [code,label,name] of [['ArrowLeft','◀','Move left'],['ArrowUp','▲','Move forward'],['ArrowDown','▼','Move backward'],['ArrowRight','▶','Move right'],['Space','⤒','Jump']]){const b=document.createElement('button');b.type='button';b.textContent=label;b.setAttribute('aria-label',name);b.style.cssText='pointer-events:auto;touch-action:none;border:1px solid #ffffff99;border-radius:12px;width:54px;height:52px;background:#132a41b8;color:white;font:bold 24px Arial;user-select:none';b.onpointerdown=e=>{e.preventDefault();active.set(e.pointerId,code);b.setPointerCapture(e.pointerId);b.style.background='#2b8cce';key(code,true);};const end=e=>{const c=active.get(e.pointerId);if(c){key(c,false);active.delete(e.pointerId);}b.style.background='#132a41b8';};b.onpointerup=end;b.onpointercancel=end;b.onlostpointercapture=end;bar.append(b);}
 document.body.append(bar);document.addEventListener('visibilitychange',()=>{if(document.hidden){for(const c of held)key(c,false);active.clear();}});
})();
